import React, { useEffect, useState } from 'react';
import api from '../services/api';

const tabs = [
  ['overview',   "📊 Vue d'ensemble"],
  ['profs',      '👨‍🏫 Professeurs'],
  ['demandes',   '💡 Demandes Matières'],
  ['referentiel','📚 Référentiel'],
];

/* ── Badge statut ── */
function StatutBadge({ statut }) {
  const cfg = {
    validé:      { bg: 'rgba(67,233,123,0.12)',  color: '#43e97b', label: '✅ Validé'      },
    en_attente:  { bg: 'rgba(245,158,11,0.12)',  color: '#f59e0b', label: '⏳ En attente'  },
    refusé:      { bg: 'rgba(255,101,132,0.12)', color: '#ff6584', label: '❌ Refusé'      },
    approuvé:    { bg: 'rgba(67,233,123,0.12)',  color: '#43e97b', label: '✅ Approuvée'   },
  }[statut] || { bg: 'var(--surface2)', color: 'var(--text2)', label: statut };
  return (
    <span style={{ fontSize: '.72rem', fontWeight: 700, padding: '3px 10px', borderRadius: 20, background: cfg.bg, color: cfg.color }}>
      {cfg.label}
    </span>
  );
}

/* ── Mode badge ── */
function ModeBadge({ mode }) {
  const map = {
    en_ligne:   { icon: '🌐', label: 'En ligne',   color: '#38bdf8', bg: 'rgba(56,189,248,0.12)'  },
    presentiel: { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.12)'  },
    les_deux:   { icon: '🔀', label: 'Les deux',   color: '#6c63ff', bg: 'rgba(108,99,255,0.12)' },
  }[mode] || { icon: '🏫', label: 'Présentiel', color: '#43e97b', bg: 'rgba(67,233,123,0.12)' };
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4, fontSize: '.72rem', fontWeight: 700, padding: '3px 9px', borderRadius: 20, background: map.bg, color: map.color }}>
      {map.icon} {map.label}
    </span>
  );
}

/* ════════════════════════════════════════════════
   CARTE PROFESSEUR
════════════════════════════════════════════════ */
function ProfCard({ prof, onView, onValider, onRefuser }) {
  const nom = `${prof.user_prenom || ''} ${prof.user_nom || ''}`.trim() || 'Professeur';

  /* matières enseignées (depuis tarifs_matieres) */
  const matieres = prof.tarifs_matieres
    ? [...new Set(prof.tarifs_matieres.map(t => t.nom_matiere))].slice(0, 3)
    : [];

  return (
    <div style={{
      background: 'var(--card)', border: '1px solid var(--border)',
      borderRadius: 20, overflow: 'hidden',
      transition: 'all .25s', cursor: 'pointer',
    }}
      onMouseEnter={e => { e.currentTarget.style.transform = 'translateY(-3px)'; e.currentTarget.style.boxShadow = '0 12px 40px rgba(108,99,255,0.18)'; e.currentTarget.style.borderColor = 'rgba(108,99,255,0.4)'; }}
      onMouseLeave={e => { e.currentTarget.style.transform = ''; e.currentTarget.style.boxShadow = ''; e.currentTarget.style.borderColor = 'var(--border)'; }}
    >
      {/* Bandeau haut */}
      <div style={{ height: 72, background: 'linear-gradient(135deg,rgba(108,99,255,.35),rgba(255,101,132,.2))', position: 'relative' }}>
        {/* Statut badge */}
        <div style={{ position: 'absolute', top: 10, right: 12 }}>
          <StatutBadge statut={prof.statut_validation} />
        </div>
        {/* Avatar */}
        <div style={{
          width: 64, height: 64, borderRadius: '50%',
          border: '3px solid var(--card)',
          background: 'linear-gradient(135deg,#6c63ff,#ff6584)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontSize: '1.5rem', overflow: 'hidden',
          position: 'absolute', bottom: -32, left: 18,
        }}>
          {prof.photo_url
            ? <img src={'http://localhost:8001' + prof.photo_url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            : '👨‍🏫'}
        </div>
      </div>

      {/* Corps */}
      <div style={{ padding: '38px 18px 18px' }}>

        {/* Nom + ville */}
        <div style={{ marginBottom: 10 }}>
          <div style={{ fontFamily: 'Syne', fontWeight: 800, fontSize: '1rem', marginBottom: 2 }}>{nom}</div>
          <div style={{ fontSize: '.78rem', color: 'var(--text2)', display: 'flex', alignItems: 'center', gap: 6 }}>
            {prof.ville && <span>📍 {prof.ville}</span>}
            <ModeBadge mode={prof.mode_enseignement} />
          </div>
        </div>

        {/* Tarifs */}
        {(prof.tarif_en_ligne || prof.tarif_presentiel) && (
          <div style={{ display: 'flex', gap: 8, marginBottom: 10 }}>
            {prof.tarif_en_ligne && (
              <div style={{ flex: 1, padding: '6px 10px', background: 'rgba(56,189,248,0.08)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 8, textAlign: 'center' }}>
                <div style={{ fontSize: '.65rem', color: '#38bdf8' }}>🌐 En ligne</div>
                <div style={{ fontWeight: 800, color: '#38bdf8', fontSize: '.9rem' }}>{prof.tarif_en_ligne} DT/h</div>
              </div>
            )}
            {prof.tarif_presentiel && (
              <div style={{ flex: 1, padding: '6px 10px', background: 'rgba(67,233,123,0.08)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 8, textAlign: 'center' }}>
                <div style={{ fontSize: '.65rem', color: '#43e97b' }}>🏫 Présentiel</div>
                <div style={{ fontWeight: 800, color: '#43e97b', fontSize: '.9rem' }}>{prof.tarif_presentiel} DT/h</div>
              </div>
            )}
          </div>
        )}

        {/* Matières */}
        {matieres.length > 0 && (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 5, marginBottom: 12 }}>
            {matieres.map(m => (
              <span key={m} style={{ fontSize: '.68rem', fontWeight: 600, padding: '2px 8px', borderRadius: 20, background: 'rgba(108,99,255,0.1)', color: '#6c63ff' }}>
                {m}
              </span>
            ))}
            {prof.tarifs_matieres && prof.tarifs_matieres.length > 3 && (
              <span style={{ fontSize: '.68rem', color: 'var(--text2)' }}>+{prof.tarifs_matieres.length - 3}</span>
            )}
          </div>
        )}

        {/* Note */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 6, marginBottom: 14, fontSize: '.8rem' }}>
          <span style={{ color: '#f59e0b' }}>★</span>
          <span style={{ fontWeight: 700 }}>{parseFloat(prof.note_moyenne || 0).toFixed(1)}</span>
          <span style={{ color: 'var(--text2)' }}>{prof.nb_avis} avis</span>
        </div>

        {/* Actions */}
        <div style={{ display: 'flex', gap: 8 }}>
          <button
            onClick={e => { e.stopPropagation(); onView(prof); }}
            style={{ flex: 1, padding: '8px', background: 'linear-gradient(135deg,#6c63ff,#8b5cf6)', color: '#fff', border: 'none', borderRadius: 9, fontWeight: 600, cursor: 'pointer', fontSize: '.8rem' }}
          >
            👁 Détails
          </button>
          {prof.statut_validation !== 'validé' && (
            <button
              onClick={e => { e.stopPropagation(); onValider(prof.id); }}
              style={{ flex: 1, padding: '8px', background: 'rgba(67,233,123,0.15)', color: '#43e97b', border: '1px solid rgba(67,233,123,0.3)', borderRadius: 9, fontWeight: 600, cursor: 'pointer', fontSize: '.8rem' }}
            >
              ✅ Valider
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

/* ════════════════════════════════════════════════
   DRAWER DÉTAIL PROFESSEUR
════════════════════════════════════════════════ */
function ProfDrawer({ prof, onClose, onValider, onRefuser }) {
  if (!prof) return null;
  const nom = `${prof.user_prenom || ''} ${prof.user_nom || ''}`.trim() || 'Professeur';
  const matieres = prof.tarifs_matieres ? [...new Set(prof.tarifs_matieres.map(t => t.nom_matiere))] : [];

  return (
    <>
      {/* Overlay */}
      <div
        onClick={onClose}
        style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(4px)', zIndex: 900 }}
      />

      {/* Drawer */}
      <div style={{
        position: 'fixed', top: 0, right: 0, bottom: 0,
        width: 480, background: 'var(--surface)',
        borderLeft: '1px solid var(--border)',
        zIndex: 901, overflowY: 'auto',
        animation: 'slideIn .25s ease',
        boxShadow: '-24px 0 80px rgba(0,0,0,0.4)',
      }}>
        <style>{`@keyframes slideIn{from{transform:translateX(100%)}to{transform:translateX(0)}}`}</style>

        {/* Header drawer */}
        <div style={{ height: 120, background: 'linear-gradient(135deg,rgba(108,99,255,.4),rgba(255,101,132,.2))', position: 'relative', flexShrink: 0 }}>
          <button
            onClick={onClose}
            style={{ position: 'absolute', top: 16, right: 16, width: 36, height: 36, borderRadius: 10, background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.15)', cursor: 'pointer', color: '#fff', fontSize: '1rem', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          >✕</button>

          {/* Avatar */}
          <div style={{
            width: 80, height: 80, borderRadius: '50%',
            border: '4px solid var(--surface)',
            background: 'linear-gradient(135deg,#6c63ff,#ff6584)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: '2rem', overflow: 'hidden',
            position: 'absolute', bottom: -40, left: 28,
          }}>
            {prof.photo_url
              ? <img src={'http://localhost:8001' + prof.photo_url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              : '👨‍🏫'}
          </div>

          {/* Statut */}
          <div style={{ position: 'absolute', bottom: -16, right: 24 }}>
            <StatutBadge statut={prof.statut_validation} />
          </div>
        </div>

        {/* Contenu */}
        <div style={{ padding: '52px 28px 28px' }}>

          {/* Nom + infos de base */}
          <div style={{ marginBottom: 20 }}>
            <h2 style={{ fontFamily: 'Syne', fontSize: '1.4rem', margin: '0 0 6px' }}>{nom}</h2>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
              {prof.ville && <span style={{ fontSize: '.82rem', color: 'var(--text2)' }}>📍 {prof.ville}</span>}
              <ModeBadge mode={prof.mode_enseignement} />
              <div style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: '.82rem' }}>
                <span style={{ color: '#f59e0b' }}>★</span>
                <span style={{ fontWeight: 700 }}>{parseFloat(prof.note_moyenne || 0).toFixed(1)}</span>
                <span style={{ color: 'var(--text2)' }}>({prof.nb_avis} avis)</span>
              </div>
            </div>
          </div>

          {/* Actions validation */}
          {prof.statut_validation !== 'validé' && (
            <div style={{ display: 'flex', gap: 10, marginBottom: 24 }}>
              <button
                onClick={() => { onValider(prof.id); onClose(); }}
                style={{ flex: 1, padding: '11px', background: 'linear-gradient(135deg,#43e97b,#38f9d7)', color: '#000', border: 'none', borderRadius: 10, fontWeight: 700, cursor: 'pointer' }}
              >
                ✅ Valider ce professeur
              </button>
              <button
                onClick={() => { onRefuser(prof.id); onClose(); }}
                style={{ flex: 1, padding: '11px', background: 'transparent', color: '#ff6584', border: '1px solid #ff6584', borderRadius: 10, fontWeight: 600, cursor: 'pointer' }}
              >
                ❌ Refuser
              </button>
            </div>
          )}

          {/* ── Coordonnées ── */}
          <Section title="📇 Coordonnées">
            <InfoRow icon="✉️" label="Email"     value={prof.email} />
            <InfoRow icon="📞" label="Téléphone" value={prof.telephone || '—'} />
            <InfoRow icon="📍" label="Ville"     value={prof.ville   || '—'} />
          </Section>

          {/* ── Bio ── */}
          {prof.bio && (
            <Section title="📝 À propos">
              <p style={{ fontSize: '.85rem', color: 'var(--text2)', lineHeight: 1.7, margin: 0 }}>{prof.bio}</p>
            </Section>
          )}

          {/* ── Tarifs ── */}
          {(prof.tarif_en_ligne || prof.tarif_presentiel) && (
            <Section title="💰 Tarifs horaires">
              <div style={{ display: 'flex', gap: 12 }}>
                {prof.tarif_en_ligne && (
                  <div style={{ flex: 1, padding: '12px', background: 'rgba(56,189,248,0.08)', border: '1px solid rgba(56,189,248,0.2)', borderRadius: 10, textAlign: 'center' }}>
                    <div style={{ fontSize: '.72rem', color: '#38bdf8', marginBottom: 4 }}>🌐 En ligne</div>
                    <div style={{ fontFamily: 'Syne', fontWeight: 800, color: '#38bdf8', fontSize: '1.2rem' }}>{prof.tarif_en_ligne} DT</div>
                    <div style={{ fontSize: '.68rem', color: 'var(--text2)' }}>/ heure</div>
                  </div>
                )}
                {prof.tarif_presentiel && (
                  <div style={{ flex: 1, padding: '12px', background: 'rgba(67,233,123,0.08)', border: '1px solid rgba(67,233,123,0.2)', borderRadius: 10, textAlign: 'center' }}>
                    <div style={{ fontSize: '.72rem', color: '#43e97b', marginBottom: 4 }}>🏫 Présentiel</div>
                    <div style={{ fontFamily: 'Syne', fontWeight: 800, color: '#43e97b', fontSize: '1.2rem' }}>{prof.tarif_presentiel} DT</div>
                    <div style={{ fontSize: '.68rem', color: 'var(--text2)' }}>/ heure</div>
                  </div>
                )}
              </div>
            </Section>
          )}

          {/* ── Matières enseignées ── */}
          {matieres.length > 0 && (
            <Section title="📚 Matières enseignées">
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                {matieres.map(m => (
                  <span key={m} style={{ fontSize: '.78rem', fontWeight: 600, padding: '4px 12px', borderRadius: 20, background: 'rgba(108,99,255,0.1)', color: '#6c63ff' }}>
                    {m}
                  </span>
                ))}
              </div>
            </Section>
          )}

          {/* ── Niveaux ── */}
          {prof.niveaux && prof.niveaux.length > 0 && (
            <Section title="🎓 Niveaux enseignés">
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                {prof.niveaux.map(n => (
                  <span key={n} style={{ fontSize: '.78rem', fontWeight: 600, padding: '4px 12px', borderRadius: 20, background: 'var(--surface2)', color: 'var(--text2)', border: '1px solid var(--border)' }}>
                    {n}
                  </span>
                ))}
              </div>
            </Section>
          )}

          {/* ── Diplômes & CV ── */}
          {prof.certificats && prof.certificats.length > 0 && (
            <Section title="📜 Diplômes & Certificats">
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                {prof.certificats.map(c => (
                  <a
                    key={c.id}
                    href={'http://localhost:8001' + c.fichier_url}
                    target="_blank"
                    rel="noreferrer"
                    style={{ textDecoration: 'none' }}
                  >
                    <div style={{
                      display: 'flex', alignItems: 'center', gap: 14,
                      padding: '12px 16px',
                      background: 'linear-gradient(135deg,rgba(108,99,255,0.08),rgba(255,101,132,0.05))',
                      border: '1px solid rgba(108,99,255,0.2)',
                      borderRadius: 12, transition: 'all .2s', cursor: 'pointer',
                    }}
                      onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(108,99,255,0.5)'; e.currentTarget.style.background = 'rgba(108,99,255,0.12)'; }}
                      onMouseLeave={e => { e.currentTarget.style.borderColor = 'rgba(108,99,255,0.2)'; e.currentTarget.style.background = 'linear-gradient(135deg,rgba(108,99,255,0.08),rgba(255,101,132,0.05))'; }}
                    >
                      <div style={{ width: 40, height: 40, borderRadius: 10, background: 'rgba(108,99,255,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem', flexShrink: 0 }}>
                        {c.fichier_url && c.fichier_url.endsWith('.pdf') ? '📄' : '🖼️'}
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <div style={{ fontWeight: 700, fontSize: '.88rem', color: 'var(--text)', marginBottom: 2 }}>{c.titre}</div>
                        {c.description && <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>{c.description}</div>}
                        <div style={{ fontSize: '.7rem', color: '#6c63ff', marginTop: 3 }}>
                          Cliquer pour consulter →
                        </div>
                      </div>
                      <div style={{ fontSize: '1.1rem', color: '#6c63ff', flexShrink: 0 }}>↗</div>
                    </div>
                  </a>
                ))}
              </div>
            </Section>
          )}

          {/* ── Disponibilités ── */}
          {prof.disponibilites && prof.disponibilites.length > 0 && (
            <Section title="🗓 Créneaux disponibles">
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                {prof.disponibilites.slice(0, 4).map(d => (
                  <div key={d.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 12px', background: 'var(--surface2)', borderRadius: 9, border: '1px solid var(--border)' }}>
                    <span style={{ fontSize: '.82rem', fontWeight: 600 }}>📆 {d.date_specifique}</span>
                    <span style={{ fontSize: '.78rem', color: 'var(--accent)' }}>🕒 {d.heure_debut} – {d.heure_fin}</span>
                    <span style={{ fontSize: '.72rem', color: d.nb_inscrits >= d.nb_max_etudiants ? '#ff6584' : '#43e97b' }}>
                      👥 {d.nb_inscrits}/{d.nb_max_etudiants}
                    </span>
                  </div>
                ))}
              </div>
            </Section>
          )}
        </div>
      </div>
    </>
  );
}

/* ── Helpers composants ── */
function Section({ title, children }) {
  return (
    <div style={{ marginBottom: 22 }}>
      <div style={{ fontSize: '.72rem', fontWeight: 800, color: 'var(--text2)', textTransform: 'uppercase', letterSpacing: '.1em', marginBottom: 12, borderBottom: '1px solid var(--border)', paddingBottom: 8 }}>
        {title}
      </div>
      {children}
    </div>
  );
}

function InfoRow({ icon, label, value }) {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '7px 0', borderBottom: '1px solid var(--border)' }}>
      <span style={{ fontSize: '.9rem', width: 20, textAlign: 'center' }}>{icon}</span>
      <span style={{ fontSize: '.8rem', color: 'var(--text2)', width: 80 }}>{label}</span>
      <span style={{ fontSize: '.85rem', fontWeight: 600, flex: 1 }}>{value}</span>
    </div>
  );
}

/* ════════════════════════════════════════════════
   COMPOSANT PRINCIPAL ADMIN
════════════════════════════════════════════════ */
export default function Admin() {
  const [tab, setTab]             = useState('overview');
  const [stats, setStats]         = useState({});
  const [profs, setProfs]         = useState([]);
  const [pending, setPending]     = useState([]);
  const [structure, setStructure] = useState([]);
  const [villes, setVilles]       = useState([]);
  const [demandes, setDemandes]   = useState([]);
  const [loading, setLoading]     = useState(true);
  const [selectedProf, setSelectedProf] = useState(null);

  const [showAddMat, setShowAddMat] = useState(false);
  const [newMat, setNewMat]         = useState({ nom: '', niveau_id: '' });

  // Filtres prof
  const [filterStatut, setFilterStatut] = useState('tous');
  const [searchProf, setSearchProf]     = useState('');

  useEffect(() => { loadAllData(); }, []);

  const loadAllData = async () => {
    setLoading(true);
    try {
      const [s, p, pend, struct, v, dem] = await Promise.all([
        api.get('/api/admin/stats'),
        api.get('/api/professeurs/'),
        api.get('/api/admin/professeurs/pending'),
        api.get('/api/admin/referentiel/structure'),
        api.get('/api/admin/referentiel/villes'),
        api.get('/api/admin/demandes-matieres'),
      ]);
      setStats(s.data);
      setProfs(p.data);
      setPending(pend.data);
      setStructure(struct.data);
      setVilles(v.data);
      setDemandes(dem.data);
    } catch (err) {
      console.error('Erreur chargement admin', err);
    } finally {
      setLoading(false);
    }
  };

  const handleValider = async (id) => {
    await api.put(`/api/admin/professeurs/${id}/valider`);
    alert('✅ Professeur validé');
    loadAllData();
  };

  const handleRefuser = async (id) => {
    if (!window.confirm('Refuser ce professeur ?')) return;
    await api.put(`/api/admin/professeurs/${id}/refuser`);
    loadAllData();
  };

  const handleAddMatiere = async (e) => {
    e.preventDefault();
    await api.post('/api/admin/referentiel/matieres', newMat);
    setShowAddMat(false);
    setNewMat({ nom: '', niveau_id: '' });
    loadAllData();
  };

  const handleApprouverDemande = async (id) => {
    try {
      await api.put(`/api/admin/demandes-matieres/${id}/approuver`);
      alert('✅ Matière approuvée et ajoutée au référentiel !');
      loadAllData();
    } catch (e) {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
    }
  };

  const handleRefuserDemande = async (id) => {
    if (!window.confirm('Refuser cette demande ?')) return;
    try {
      await api.put(`/api/admin/demandes-matieres/${id}/refuser`);
      loadAllData();
    } catch (e) {
      alert('Erreur : ' + (e.response?.data?.detail || e.message));
    }
  };

  const tabStyle = (t) => ({
    flex: 1, padding: '11px', textAlign: 'center', borderRadius: 12,
    cursor: 'pointer', fontWeight: 600, fontSize: '.88rem', transition: '.2s',
    background: tab === t ? '#6c63ff' : 'transparent',
    color: tab === t ? '#fff' : 'var(--text2)', border: 'none',
    position: 'relative',
  });

  const demandesPending = demandes.filter(d => d.statut === 'en_attente').length;

  // Profs filtrés
  const profsFiltered = profs.filter(p => {
    const nom = `${p.user_prenom || ''} ${p.user_nom || ''}`.toLowerCase();
    const matchSearch = !searchProf || nom.includes(searchProf.toLowerCase()) || (p.ville || '').toLowerCase().includes(searchProf.toLowerCase());
    const matchStatut = filterStatut === 'tous' || p.statut_validation === filterStatut;
    return matchSearch && matchStatut;
  });

  const statCards = [
    { icon: '👥', val: stats.total_users              || 0, lbl: 'Utilisateurs',      color: '#6c63ff', bg: 'rgba(108,99,255,.1)'  },
    { icon: '👨‍🏫', val: stats.total_professeurs        || 0, lbl: 'Profs validés',     color: '#43e97b', bg: 'rgba(67,233,123,.1)'  },
    { icon: '⏳', val: stats.en_attente                || 0, lbl: 'En attente',        color: '#f59e0b', bg: 'rgba(245,158,11,.1)'  },
    { icon: '📅', val: stats.total_reservations        || 0, lbl: 'Réservations',      color: '#38bdf8', bg: 'rgba(56,189,248,.1)'  },
    { icon: '💡', val: stats.demandes_matieres_pending || 0, lbl: 'Demandes matières', color: '#ff6584', bg: 'rgba(255,101,132,.1)' },
  ];

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '9px 14px', fontSize: '.85rem', outline: 'none' };

  return (
    <div style={{ padding: 32, maxWidth: 1300, margin: '0 auto' }}>
      <div style={{ fontFamily: 'Syne', fontSize: '1.8rem', fontWeight: 800, marginBottom: 32 }}>
        🛠 Dashboard Admin
      </div>

      {/* ── STATS ── */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5,1fr)', gap: 16, marginBottom: 32 }}>
        {statCards.map(s => (
          <div key={s.lbl} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 20 }}>
            <div style={{ width: 44, height: 44, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1.2rem', marginBottom: 14 }}>{s.icon}</div>
            <div style={{ fontFamily: 'Syne', fontSize: '1.7rem', fontWeight: 800, color: s.color }}>{s.val}</div>
            <div style={{ fontSize: '.8rem', color: 'var(--text2)' }}>{s.lbl}</div>
          </div>
        ))}
      </div>

      {/* ── ONGLETS ── */}
      <div style={{ display: 'flex', background: 'var(--surface2)', borderRadius: 16, padding: 6, marginBottom: 32, gap: 4 }}>
        {tabs.map(([k, l]) => (
          <button key={k} style={tabStyle(k)} onClick={() => setTab(k)}>
            {l}
            {k === 'demandes' && demandesPending > 0 && (
              <span style={{ position: 'absolute', top: 4, right: 8, background: '#ff6584', color: '#fff', fontSize: '.6rem', fontWeight: 800, padding: '1px 6px', borderRadius: 20, minWidth: 18, textAlign: 'center' }}>
                {demandesPending}
              </span>
            )}
          </button>
        ))}
      </div>

      {/* ════════ VUE D'ENSEMBLE ════════ */}
      {tab === 'overview' && (
        <div style={{ display: 'grid', gridTemplateColumns: '1.2fr 0.8fr', gap: 24 }}>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <div style={{ fontWeight: 700, marginBottom: 20 }}>📊 Activité récente</div>
            <p style={{ color: 'var(--text2)' }}>{stats.reservations_mois} nouvelles réservations ce mois-ci.</p>
            {demandesPending > 0 && (
              <div onClick={() => setTab('demandes')} style={{ marginTop: 16, padding: '12px 16px', background: 'rgba(255,101,132,0.08)', border: '1px solid rgba(255,101,132,0.25)', borderRadius: 12, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 10 }}>
                <span style={{ fontSize: '1.2rem' }}>💡</span>
                <div>
                  <div style={{ fontWeight: 700, fontSize: '.88rem', color: '#ff6584' }}>
                    {demandesPending} demande{demandesPending > 1 ? 's' : ''} de matière en attente
                  </div>
                  <div style={{ fontSize: '.75rem', color: 'var(--text2)' }}>Cliquez pour examiner</div>
                </div>
              </div>
            )}
          </div>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <div style={{ fontWeight: 700, marginBottom: 20 }}>🏆 Top Professeurs</div>
            {profs.slice(0, 4).map(p => (
              <div key={p.id} onClick={() => { setTab('profs'); setSelectedProf(p); }} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '10px 0', borderBottom: '1px solid var(--border)', cursor: 'pointer' }}>
                <span style={{ fontSize: '.88rem' }}>{p.user_prenom} {p.user_nom}</span>
                <span style={{ color: '#f59e0b', fontWeight: 700 }}>★ {parseFloat(p.note_moyenne || 0).toFixed(1)}</span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ════════ PROFESSEURS ════════ */}
      {tab === 'profs' && (
        <div>
          {/* En attente de validation */}
          {pending.length > 0 && (
            <div style={{ marginBottom: 28, background: 'var(--card)', border: '1px solid rgba(245,158,11,0.3)', borderRadius: 20, padding: 20 }}>
              <div style={{ color: '#f59e0b', fontWeight: 700, fontSize: '.88rem', marginBottom: 14 }}>
                ⚠️ EN ATTENTE DE VALIDATION ({pending.length})
              </div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                {pending.map(p => (
                  <div key={p.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 16px', background: 'rgba(245,158,11,0.05)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: 12 }}>
                    <div>
                      <div style={{ fontWeight: 700 }}>{p.nom}</div>
                      <div style={{ fontSize: '.78rem', color: 'var(--text2)' }}>{p.email}</div>
                    </div>
                    <div style={{ display: 'flex', gap: 8 }}>
                      <button onClick={() => handleValider(p.id)} style={{ padding: '7px 14px', background: '#43e97b', color: '#000', border: 'none', borderRadius: 9, fontWeight: 700, cursor: 'pointer', fontSize: '.82rem' }}>✅ Valider</button>
                      <button onClick={() => handleRefuser(p.id)} style={{ padding: '7px 14px', background: 'transparent', color: '#ff6584', border: '1px solid #ff6584', borderRadius: 9, fontWeight: 600, cursor: 'pointer', fontSize: '.82rem' }}>❌ Refuser</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Filtres */}
          <div style={{ display: 'flex', gap: 12, marginBottom: 24, alignItems: 'center' }}>
            <input
              style={{ ...inp, flex: 1 }}
              placeholder="🔍 Rechercher par nom ou ville..."
              value={searchProf}
              onChange={e => setSearchProf(e.target.value)}
            />
            <select style={{ ...inp }} value={filterStatut} onChange={e => setFilterStatut(e.target.value)}>
              <option value="tous">Tous les statuts</option>
              <option value="validé">Validés</option>
              <option value="en_attente">En attente</option>
              <option value="refusé">Refusés</option>
            </select>
            <div style={{ fontSize: '.82rem', color: 'var(--text2)', whiteSpace: 'nowrap' }}>
              {profsFiltered.length} professeur{profsFiltered.length !== 1 ? 's' : ''}
            </div>
          </div>

          {/* Grille de cartes */}
          {profsFiltered.length === 0 ? (
            <div style={{ textAlign: 'center', padding: '60px 20px', color: 'var(--text2)', background: 'var(--card)', borderRadius: 20, border: '1px solid var(--border)' }}>
              <div style={{ fontSize: '2.5rem', marginBottom: 12 }}>🔍</div>
              <div style={{ fontWeight: 600 }}>Aucun professeur trouvé</div>
            </div>
          ) : (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 20 }}>
              {profsFiltered.map(p => (
                <ProfCard
                  key={p.id}
                  prof={p}
                  onView={setSelectedProf}
                  onValider={handleValider}
                  onRefuser={handleRefuser}
                />
              ))}
            </div>
          )}
        </div>
      )}

      {/* ════════ DEMANDES MATIÈRES ════════ */}
      {tab === 'demandes' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3,1fr)', gap: 16 }}>
            {[
              { label: 'En attente', count: demandes.filter(d => d.statut === 'en_attente').length, color: '#f59e0b', bg: 'rgba(245,158,11,0.1)' },
              { label: 'Approuvées', count: demandes.filter(d => d.statut === 'approuvé').length,   color: '#43e97b', bg: 'rgba(67,233,123,0.1)'  },
              { label: 'Refusées',   count: demandes.filter(d => d.statut === 'refusé').length,     color: '#ff6584', bg: 'rgba(255,101,132,0.1)' },
            ].map(s => (
              <div key={s.label} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 16, padding: '16px 20px', display: 'flex', alignItems: 'center', gap: 14 }}>
                <div style={{ width: 44, height: 44, borderRadius: 12, background: s.bg, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <span style={{ fontFamily: 'Syne', fontSize: '1.3rem', fontWeight: 800, color: s.color }}>{s.count}</span>
                </div>
                <div style={{ fontSize: '.85rem', color: 'var(--text2)', fontWeight: 600 }}>{s.label}</div>
              </div>
            ))}
          </div>

          {demandes.filter(d => d.statut === 'en_attente').length > 0 && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginTop: 0, marginBottom: 20, color: '#f59e0b' }}>⏳ Demandes en attente</h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                {demandes.filter(d => d.statut === 'en_attente').map(d => (
                  <div key={d.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '16px 20px', background: 'rgba(245,158,11,0.05)', border: '1px solid rgba(245,158,11,0.2)', borderRadius: 14 }}>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 700, fontSize: '1rem', marginBottom: 4 }}>💡 {d.nom_matiere}</div>
                      <div style={{ display: 'flex', gap: 12, fontSize: '.8rem', color: 'var(--text2)' }}>
                        <span>🎓 {d.nom_niveau}</span>
                        <span>👨‍🏫 {d.prof_nom}</span>
                        <span>🕐 {new Date(d.created_at).toLocaleDateString('fr-FR')}</span>
                      </div>
                    </div>
                    <div style={{ display: 'flex', gap: 10, flexShrink: 0 }}>
                      <button onClick={() => handleApprouverDemande(d.id)} style={{ padding: '9px 18px', background: 'linear-gradient(135deg,#43e97b,#38f9d7)', color: '#000', border: 'none', borderRadius: 10, fontWeight: 700, cursor: 'pointer', fontSize: '.85rem' }}>✅ Approuver</button>
                      <button onClick={() => handleRefuserDemande(d.id)} style={{ padding: '9px 18px', background: 'transparent', color: '#ff6584', border: '1px solid #ff6584', borderRadius: 10, fontWeight: 600, cursor: 'pointer', fontSize: '.85rem' }}>❌ Refuser</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {demandes.filter(d => d.statut === 'en_attente').length === 0 && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 40, textAlign: 'center', color: 'var(--text2)' }}>
              <div style={{ fontSize: '2rem', marginBottom: 10 }}>✅</div>
              <div style={{ fontWeight: 600 }}>Aucune demande en attente</div>
            </div>
          )}

          {demandes.filter(d => d.statut !== 'en_attente').length > 0 && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginTop: 0, marginBottom: 20 }}>📋 Historique</h3>
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr style={{ textAlign: 'left', color: 'var(--text2)', fontSize: '.78rem', borderBottom: '1px solid var(--border)' }}>
                    {['MATIÈRE','NIVEAU','PROFESSEUR','DATE','STATUT'].map(h => <th key={h} style={{ padding: '10px 12px' }}>{h}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {demandes.filter(d => d.statut !== 'en_attente').map(d => (
                    <tr key={d.id} style={{ borderBottom: '1px solid var(--border)' }}>
                      <td style={{ padding: '12px', fontWeight: 600 }}>{d.nom_matiere}</td>
                      <td style={{ padding: '12px', fontSize: '.85rem', color: 'var(--text2)' }}>{d.nom_niveau}</td>
                      <td style={{ padding: '12px', fontSize: '.85rem' }}>{d.prof_nom}</td>
                      <td style={{ padding: '12px', fontSize: '.82rem', color: 'var(--text2)' }}>{new Date(d.created_at).toLocaleDateString('fr-FR')}</td>
                      <td style={{ padding: '12px' }}><StatutBadge statut={d.statut} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* ════════ RÉFÉRENTIEL ════════ */}
      {tab === 'referentiel' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 32 }}>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 20 }}>
              <h3 style={{ fontFamily: 'Syne', margin: 0 }}>📍 Villes actives</h3>
              <button style={{ background: 'var(--surface2)', color: 'var(--text)', border: '1px solid var(--border)', padding: '6px 14px', borderRadius: 8, cursor: 'pointer' }}>+ Ajouter</button>
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10 }}>
              {villes.map(v => <span key={v.id} style={{ background: 'var(--surface2)', padding: '8px 16px', borderRadius: 12, border: '1px solid var(--border)', fontSize: '.9rem' }}>{v.nom}</span>)}
            </div>
          </div>

          {structure.map(dom => (
            <div key={dom.id} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ color: '#6c63ff', fontFamily: 'Syne', marginBottom: 24, marginTop: 0, fontSize: '1.3rem' }}>📁 {dom.nom}</h3>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
                {dom.niveaux?.map(niv => (
                  <div key={niv.id} style={{ background: 'var(--surface2)', padding: 18, borderRadius: 16, border: '1px solid var(--border)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14, borderBottom: '1px solid var(--border)', paddingBottom: 10 }}>
                      <span style={{ fontWeight: 800, fontSize: '.9rem' }}>🎓 {niv.nom}</span>
                      <button onClick={() => { setNewMat({ ...newMat, niveau_id: niv.id }); setShowAddMat(true); }} style={{ background: 'none', border: 'none', color: '#6c63ff', cursor: 'pointer', fontWeight: 700, fontSize: '.78rem' }}>+ AJOUTER</button>
                    </div>
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                      {niv.matieres?.map(m => (
                        <div key={m.id} style={{ background: 'var(--card)', padding: '6px 12px', borderRadius: 8, fontSize: '.8rem', border: '1px solid var(--border)', display: 'flex', gap: 8, alignItems: 'center' }}>
                          {m.nom}
                          <span style={{ color: '#ff6584', cursor: 'pointer', fontSize: '.75rem' }}>✕</span>
                        </div>
                      ))}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* ── MODALE AJOUT MATIÈRE ── */}
      {showAddMat && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.8)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ background: 'var(--surface)', padding: 32, borderRadius: 24, width: 400, border: '1px solid var(--border)' }}>
            <h3 style={{ marginBottom: 20, marginTop: 0 }}>Nouvelle matière</h3>
            <form onSubmit={handleAddMatiere} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
              <input style={{ width: '100%', background: 'var(--surface2)', border: '1px solid var(--border)', padding: 12, borderRadius: 10, color: '#fff', outline: 'none' }} placeholder="Nom de la matière" value={newMat.nom} onChange={e => setNewMat({ ...newMat, nom: e.target.value })} required />
              <div style={{ display: 'flex', gap: 10 }}>
                <button type="submit" style={{ flex: 2, background: '#6c63ff', color: '#fff', border: 'none', padding: 12, borderRadius: 10, fontWeight: 700, cursor: 'pointer' }}>Enregistrer</button>
                <button type="button" onClick={() => setShowAddMat(false)} style={{ flex: 1, background: 'var(--surface2)', color: '#fff', border: 'none', padding: 12, borderRadius: 10, cursor: 'pointer' }}>Annuler</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ── DRAWER DÉTAIL PROF ── */}
      <ProfDrawer
        prof={selectedProf}
        onClose={() => setSelectedProf(null)}
        onValider={handleValider}
        onRefuser={handleRefuser}
      />
    </div>
  );
}
